-- ------------------------------------------------ access: The Hole -> Brell's Rest
-- live PEQ ships only the one-way coordinate-less row; add the reverse
-- portal and give the outbound row real source coordinates (both anchored
-- to the Useful Automated Vendor at 9,466,152.6). Idempotent on number,
-- and the pre-existing duplicate outbound rows are collapsed.
DELETE FROM `zone_points` WHERE `zone` = 'hole' AND `number` = 250;
INSERT INTO `zone_points` (`zone`,`version`,`number`,`target_zone_id`,
`y`,`x`,`z`,`heading`,`target_y`,`target_x`,`target_z`,`target_heading`,
`zoneinst`,`target_instance`,`buffer`,`client_version_mask`,
`min_expansion`,`max_expansion`,`is_virtual`)
SELECT 'hole',0,250,480,744.0,209.0,-889.0,0,466.0,9.0,152.625,0,
0,0,0,4294967295,-1,-1,0;
UPDATE `zone_points` SET `x` = 9.0, `y` = 466.0, `z` = 152.625
WHERE `zone` = 'brellsrest' AND `target_zone_id` = 39
  AND `x` = 0 AND `y` = 0 AND `z` = 0;
DELETE zp1 FROM `zone_points` zp1 JOIN `zone_points` zp2
  ON zp1.zone = zp2.zone AND zp1.target_zone_id = zp2.target_zone_id
  AND zp1.number = zp2.number AND zp1.id > zp2.id
WHERE zp1.zone = 'brellsrest' AND zp1.target_zone_id = 39;
